import os
import re
from typing import Any, Dict, List, Optional

import requests


OPENAI_API_KEY = os.environ["OPENAI_API_KEY"]
OPENAI_RESPONSES_URL = "https://api.openai.com/v1/responses"
OPENAI_MODEL = "gpt-4.1-mini"


def _extract_json_text(response_json: Dict[str, Any]) -> str:
    output = response_json.get("output", [])
    texts: List[str] = []
    for item in output:
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                texts.append(content.get("text", ""))
    return "".join(texts).strip()


def _find_spans(text: str, span_text: str) -> List[Dict[str, int]]:
    if not span_text:
        return []
    spans = []
    start = 0
    while True:
        idx = text.find(span_text, start)
        if idx == -1:
            break
        spans.append({"start": idx, "end": idx + len(span_text)})
        start = idx + len(span_text)
    return spans


def _normalize_labels(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized = []
    for item in items:
        span_text = str(item.get("text", ""))
        category = str(item.get("category", "unsafe")).strip() or "unsafe"
        severity = str(item.get("severity", "medium")).strip() or "medium"
        reason = str(item.get("reason", "")).strip()
        normalized.append(
            {
                "text": span_text,
                "category": category,
                "severity": severity,
                "reason": reason,
            }
        )
    return normalized


def flag_unsafe_spans(text: str) -> Dict[str, Any]:
    headers = {
        "Authorization": f"Bearer {OPENAI_API_KEY}",
        "Content-Type": "application/json",
    }

    schema = {
        "name": "unsafe_spans",
        "schema": {
            "type": "object",
            "additionalProperties": False,
            "properties": {
                "unsafe": {"type": "boolean"},
                "items": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "additionalProperties": False,
                        "properties": {
                            "text": {"type": "string"},
                            "category": {"type": "string"},
                            "severity": {"type": "string"},
                            "reason": {"type": "string"},
                        },
                        "required": ["text", "category", "severity", "reason"],
                    },
                },
            },
            "required": ["unsafe", "items"],
        },
    }

    prompt = (
        "Identify unsafe spans in the user's text. Unsafe includes hateful, harassing, "
        "sexual involving minors, self-harm encouragement, violent threats, extremist praise, "
        "or explicit instructions for wrongdoing. Return only exact substrings from the text "
        "that are unsafe. If nothing is unsafe, return unsafe=false and an empty items array."
    )

    payload = {
        "model": OPENAI_MODEL,
        "input": [
            {"role": "system", "content": prompt},
            {"role": "user", "content": text},
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": schema["name"],
                "schema": schema["schema"],
                "strict": True,
            }
        },
    }

    response = requests.post(OPENAI_RESPONSES_URL, headers=headers, json=payload, timeout=60)
    response.raise_for_status()
    data = response.json()
    parsed = _extract_json_text(data)
    result = __import__("json").loads(parsed)

    items = _normalize_labels(result.get("items", []))
    flagged = []
    for item in items:
        matches = _find_spans(text, item["text"])
        if matches:
            for match in matches:
                flagged.append(
                    {
                        "start": match["start"],
                        "end": match["end"],
                        "text": text[match["start"]:match["end"]],
                        "category": item["category"],
                        "severity": item["severity"],
                        "reason": item["reason"],
                    }
                )

    flagged.sort(key=lambda x: (x["start"], x["end"]))
    return {
        "unsafe": bool(result.get("unsafe")) and bool(flagged),
        "spans": flagged,
    }


def redact_unsafe_spans(text: str, redaction_token: str = "[REDACTED]") -> Dict[str, Any]:
    flagged = flag_unsafe_spans(text)
    spans = flagged["spans"]
    if not spans:
        return {
            "unsafe": False,
            "redacted_text": text,
            "spans": [],
        }

    merged: List[Dict[str, Any]] = []
    for span in spans:
        if not merged or span["start"] > merged[-1]["end"]:
            merged.append({"start": span["start"], "end": span["end"]})
        else:
            merged[-1]["end"] = max(merged[-1]["end"], span["end"])

    parts = []
    last = 0
    for span in merged:
        parts.append(text[last:span["start"]])
        parts.append(redaction_token)
        last = span["end"]
    parts.append(text[last:])

    redacted_text = "".join(parts)
    return {
        "unsafe": True,
        "redacted_text": redacted_text,
        "spans": spans,
    }
